def esc(s): return s.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;').replace('|','&#124;').replace('\n','<br>') or '（該当文章なし）'
def ids(expr):
    out=[]
    for part in expr.split(','):
        if '-' in part:
            a,b=part.split('-'); out += [f'D{i:02}' for i in range(int(a[1:]),int(b[1:])+1)]
        else: out.append(part)
    return out
covered=set(sum((ids(s[1]) for s in specs),[]))
assert covered == {r['id'] for r in data}, ({r['id'] for r in data}-covered)
counts=Counter(r['status'] for r in data)
report=['# 3版の改訂比較・採用判断表','',
'対象：original.md（元）／oka.md（改訂）／matsuda.md（別の改訂）。2026-10-14作成。元の3ファイルは変更していません。','',
f'元ファイル基準の差分は **{len(data)}ブロック**です（okaのみ {counts["okaのみ改訂"]}、matsudaのみ {counts["matsudaのみ改訂"]}、双方が異なる改訂 {counts["双方が異なる改訂"]}）。採用判断しやすいよう **32項目**にまとめました。削除・書式変更も含みます。','',
'**最初にC02（設定方式）、C03（授業Wi-Fi）、C19（標準キャラクター）、C24（返答制限）を決めると、関連する章の選択が整理できます。** 同じ行の競合だけでなく、既存説明の削除、章をまたぐ整合性も判断対象にしています。','',
'「変更なし」はoriginalと同じという意味です。片方だけの改訂でも、削除や運用方針の変更は自動採用せず判断欄に載せています。「保持可能」は統合案であり、採用決定ではありません。技術的な主張はファイルの記載を比較したもので、実機・配布コード・外部サイトで正否を検証したものではありません。','',
'採用欄には `oka`／`matsuda`／`両方（統合）`／`original維持`／`独自案` を記入できます。C02は `SD`／`本体に直接書き込み`／`両方式併記` で指定してください。D番号は[差分原文一覧](comparison_details.md)に対応します。同じ差分が複数の判断項目にまたがる場合があります。','',
'| ID | 対象・差分番号 | original（元） | okaの改訂 | matsudaの改訂 | 区分・統合時の判断 | 採用・メモ |',
'|---|---|---|---|---|---|---|']
for id,refs,title,b,o,m,kind,note in specs:
    report.append('| '+' | '.join([id,esc(title)+'<br>'+refs,esc(b),esc(o),esc(m),esc(kind)+'<br>'+esc(note),'未決定'])+' |')
report += ['', '## 回答の書き方', '', '`C02＝本体に直接書き込み、C03＝okaの授業Wi-Fi説明を保持、C19＝basic、C24＝2文・60字。他は両方を保持。ただしC06は保留` のように指定できます。競合や削除を含む項目の判断後、関連する参照・ファイルパス・工程をそろえて1つのマニュアルへ統合できます。']
(root/'comparison.md').write_text('\n'.join(report)+'\n',encoding='utf-8')
details=['# 差分原文一覧（3版対照）','',
'[採用判断表へ戻る](comparison.md)。D番号は行単位の差分を元ファイル上の位置で統合したものです。文章を要約せず表示しています。空行は改行で表し、改行コードやUTF-8 BOMの有無は内容比較の対象外です。章の大きな組み替えでは、同じ文が対応づけられて差分が細かく分かれるため、採用判断は比較表のC番号を使ってください。','']
for r in data:
    a,b=r['start'],r['end']
    where=f'{a}〜{b}行' if b>=a else f'{a}行の直前に挿入'
    details += [f"## {r['id']}　{r['status']}", '',r['section']+'<br>元ファイル：'+f'[{where}](original.md:{a})','',
    '| original | oka | matsuda |','|---|---|---|', '| '+' | '.join(esc(r[n]) for n in ['original','oka','matsuda'])+' |','']
(root/'comparison_details.md').write_text('\n'.join(details),encoding='utf-8')
print(json.dumps(dict(blocks=len(data),counts=dict(counts),decisions=len(specs),coverage=len(covered)),ensure_ascii=False))
